package com.delivery.platform.identity.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
import java.io.IOException; import java.util.stream.*;
@Component public class JwtFilter extends OncePerRequestFilter {private final JwtService jwt;private final IdentityPrincipalLoader principals;public JwtFilter(JwtService jwt,IdentityPrincipalLoader principals){this.jwt=jwt;this.principals=principals;} protected void doFilterInternal(HttpServletRequest q,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=q.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var token=jwt.parse(h.substring(7));var p=principals.load(token.userId(),token.tenantId()).orElseThrow();var a=Stream.concat(p.roles().stream().map(x->"ROLE_"+x),p.permissions().stream()).map(SimpleGrantedAuthority::new).toList();SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(p,null,a));}catch(Exception ignored){SecurityContextHolder.clearContext();}c.doFilter(q,s);}}
